TEST_CASE("zipf") {
  auto g = mltest::load_distribution_golden("zipf");
  auto v = as_ints(g.data);
  auto r = cppunivariate::zipf_mle(as_ispan(v), mltest::kFitTol, mltest::kFitMaxit);
  CHECK(r.N == doctest::Approx(g.estimates.at("N")).epsilon(mltest::kGolden_zipf).scale(0));
  CHECK(r.shape == doctest::Approx(g.estimates.at("s")).epsilon(mltest::kGolden_zipf).scale(0));
  CHECK(r.logLik == doctest::Approx(g.logLik).epsilon(mltest::kGolden_zipf).scale(0));
}

TEST_CASE("zipf: endpoint, shape and joint holds") {
  const std::vector<int> x={1,1,2,4},ones={1,1};
  const double nan=std::numeric_limits<double>::quiet_NaN();
  for(double N:{nan,8.})for(double s:{nan,.7}) {
    const auto f=cppunivariate::zipf_mle({x.data(),x.size()},1e-10,100,N,s);
    CHECK(f.status==cppunivariate::ZipfStatus::Ok);
    CHECK(f.N==(std::isnan(N)?4:N));
    if(!std::isnan(s))CHECK(f.shape==s);
    double ll=0;for(int v:x)ll+=dist::dzipf(v,f.N,f.shape,true);
    CHECK(f.logLik==doctest::Approx(ll).epsilon(1e-12));
  }
  CHECK(cppunivariate::zipf_mle({ones.data(),ones.size()},1e-10,100,8).status==cppunivariate::ZipfStatus::PointMass);
  CHECK(cppunivariate::zipf_mle({x.data(),x.size()},1e-10,100,3).status==cppunivariate::ZipfStatus::InvalidInput);
  CHECK(cppunivariate::zipf_mle({x.data(),x.size()},1e-10,100,nan,-1).status==cppunivariate::ZipfStatus::InvalidInput);
}

TEST_CASE("zipf: structured stop payloads") {
  const std::vector<int> x{1,1};
  const auto r=cppunivariate::zipf_mle({x.data(),x.size()},1e-8,100,4);
  REQUIRE(r.stop_detail.limit_coef.size()==1);
  CHECK(r.stop_detail.limit_model==cppunivariate::StopModel::PointMass);
  CHECK(r.stop_detail.limit_coef[0]==1);
  CHECK(r.stop_detail.limit_loglik==0);
  CHECK(r.stop_detail.candidates.size()==1);
}

